import org.audiveris.omr.sheet.Book;import java.util.*;import java.nio.file.*;import java.lang.reflect.*;import java.awt.geom.*;
public class StemPartsFilterProbe extends GridFinalProbe {
 private final Object book;public StemPartsFilterProbe(Book b,SortedSet<Integer> ids){super(b,ids);book=b;}
 static Object call(Object o,String name,Object...args)throws Exception{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())for(Method m:c.getDeclaredMethods())if(m.getName().equals(name)&&m.getParameterCount()==args.length){m.setAccessible(true);return m.invoke(o,args);}throw new NoSuchMethodException(name);}
 static Object en(String c,String n)throws Exception{return Class.forName("org.audiveris.omr."+c).getField(n).get(null);}
 static void set(Object o,String n,Object v)throws Exception{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(n);f.setAccessible(true);f.set(o,v);return;}catch(NoSuchFieldException e){}throw new NoSuchFieldException(n);}
 static Object table(byte[] pixels,int w,int h,String orientation)throws Exception {Object bp=Class.forName("ij.process.ByteProcessor").getConstructor(int.class,int.class,byte[].class).newInstance(w,h,pixels);Object f=Class.forName("org.audiveris.omr.run.RunTableFactory").getConstructor(Class.forName("org.audiveris.omr.run.Orientation")).newInstance(en("run.Orientation",orientation));return f.getClass().getMethod("createTable",Class.forName("ij.process.ByteProcessor")).invoke(f,bp);}
 static Object glyph(int x,int y,int w,int h,String orientation)throws Exception{return Class.forName("org.audiveris.omr.glyph.Glyph").getConstructor(int.class,int.class,Class.forName("org.audiveris.omr.run.RunTable")).newInstance(x,y,table(new byte[w*h],w,h,orientation));}
 static String physical(Object g)throws Exception {Object t=call(g,"getRunTable");List<String> runs=new ArrayList<>();for(int i=0;i<(Integer)call(t,"getSize");i++){Iterator<?> it=(Iterator<?>)call(t,"iterator",i);while(it.hasNext()){Object r=it.next();runs.add("["+i+","+call(r,"getStart")+","+call(r,"getLength")+"]");}}return "{\"bounds\":"+rect(call(g,"getBounds"))+",\"orientation\":\""+call(t,"getOrientation")+"\",\"runs\":["+String.join(",",runs)+"]}";}
 static String impacts(Object p)throws Exception {if(p==null)return "null";List<String> vals=new ArrayList<>();for(int i=0;i<(Integer)call(p,"getImpactCount");i++)vals.add("{\"name\":\""+call(p,"getName",i)+"\",\"weight\":"+call(p,"getWeight",i)+",\"impact\":"+call(p,"getImpact",i)+"}");return "{\"grade\":"+call(p,"getGrade")+",\"intrinsic_ratio\":"+call(p,"getIntrinsicRatio")+",\"checks\":["+String.join(",",vals)+"]}";}
 static String stem(Object s)throws Exception {if(s==null)return "null";Line2D m=(Line2D)call(s,"getMedian");return "{\"grade\":"+call(s,"getGrade")+",\"bounds\":"+rect(call(s,"getBounds"))+",\"median\":["+m.getX1()+","+m.getY1()+","+m.getX2()+","+m.getY2()+"],\"width\":"+call(s,"getWidth")+",\"glyph\":"+physical(call(s,"getGlyph"))+",\"impacts\":"+impacts(call(s,"getImpacts"))+",\"in_sig\":"+(call(s,"getSig")!=null)+",\"id\":"+call(s,"getId")+"}";}
 static int gid(IdentityHashMap<Object,Integer> ids,List<Object> glyphs,Object g){if(g==null)return 0;Integer id=ids.get(g);if(id==null){id=glyphs.size()+1;ids.put(g,id);glyphs.add(g);}return id;}
 static String point(Object p){Point2D v=(Point2D)p;return "["+v.getX()+","+v.getY()+"]";}
 static String observe(Object sb,List<Object> parts,List<Object> linkers,Object headBox,String mode)throws Exception{
  Object start=get(sb,"startLinker"),stump=call(start,"getStump"),params=get(sb,"params"),sys=get(sb,"system");IdentityHashMap<Object,Integer> ids=new IdentityHashMap<>(),lids=new IdentityHashMap<>();List<Object> glyphs=new ArrayList<>();int sid=gid(ids,glyphs,stump);
  List<String> lr=new ArrayList<>(),lo=new ArrayList<>();for(Object l:linkers){int lid=lids.computeIfAbsent(l,k->lids.size()+1),id=gid(ids,glyphs,call(l,"getStump"));lo.add(""+lid);if(lr.size()>=lid)continue;String kind=l.getClass().getSimpleName();Object source=call(l,"getSource");boolean half=Class.forName("org.audiveris.omr.sheet.stem.StemHalfLinker").isInstance(l);lr.add("{\"id\":"+lid+",\"kind\":\""+kind+"\",\"half\":"+half+",\"stump_id\":"+(id==0?"null":id)+",\"reference\":"+point(call(l,"getReferencePoint"))+",\"beam_height\":"+(kind.equals("BLinker")?call(source,"getHeight"):"null")+"}");}
  List<String> po=new ArrayList<>();for(Object g:parts)po.add(""+gid(ids,glyphs,g));List<String> gr=new ArrayList<>();for(Object g:glyphs)gr.add("{\"id\":"+ids.get(g)+",\"glyph\":"+physical(g)+"}");
  List<?> filtered=(List<?>)call(sb,"filter",headBox,parts,linkers);List<String> kept=new ArrayList<>(),kl=new ArrayList<>(),ir=new ArrayList<>();for(Object g:parts)kept.add(""+ids.get(g));for(Object l:linkers)kl.add(""+lids.get(l));for(Object item:filtered){Line2D line=(Line2D)get(item,"line");Object g=get(item,"glyph"),l=null;if(item.getClass().getSimpleName().contains("LinkerItem"))l=get(item,"linker");ir.add("{\"kind\":\""+item.getClass().getSimpleName()+"\",\"contrib\":"+get(item,"contrib")+",\"line\":["+line.getX1()+","+line.getY1()+","+line.getX2()+","+line.getY2()+"],\"glyph_id\":"+(g==null?"null":ids.get(g))+",\"linker_id\":"+(l==null?"null":lids.get(l))+"}");}
  return "{\"start_kind\":\""+start.getClass().getSimpleName()+"\",\"direction\":"+get(sb,"yDir")+",\"slope\":"+call(call(sys,"getSkew"),"getSlope")+",\"max_alignment_dx\":"+get(params,"maxStemAlignmentDx")+",\"max_alignment_dy\":"+get(params,"maxStemAlignmentDy")+",\"y_range\":"+rect(get(sb,"yRange"))+",\"start_stump_id\":"+(sid==0?"null":sid)+",\"head_box\":"+(headBox==null?"null":rect(headBox))+",\"mode\":\""+mode+"\",\"glyphs\":["+String.join(",",gr)+"],\"linkers\":["+String.join(",",lr)+"],\"part_order\":["+String.join(",",po)+"],\"linker_order\":["+String.join(",",lo)+"],\"retained_part_order\":["+String.join(",",kept)+"],\"retained_linker_order\":["+String.join(",",kl)+"],\"last_head_y\":"+get(sb,"lastHeadY")+",\"items\":["+String.join(",",ir)+"]}";
 }
 public void process(){try{
  Object sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet"),sys=((List<?>)call(sheet,"getSystems")).get(0);Object retr=Class.forName("org.audiveris.omr.sheet.stem.StemsRetriever").getConstructor(Class.forName("org.audiveris.omr.sheet.SystemInfo")).newInstance(sys);call(retr,"process");
  Set<Object> seen=Collections.newSetFromMap(new IdentityHashMap<>());List<Object> builders=new ArrayList<>();for(Object head:(List<?>)get(retr,"systemHeads")){Object linker=call(head,"getLinker");if(linker==null)continue;for(String side:new String[]{"LEFT","RIGHT"})for(String vert:new String[]{"TOP","BOTTOM"}){Object corner=call(linker,"getCornerLinker",en("util.HorizontalSide",side),en("util.VerticalSide",vert)),sb=get(corner,"sb");if(sb!=null&&seen.add(sb))builders.add(sb);}}
  for(Object beam:(List<?>)get(retr,"systemBeams")){Object linker=call(beam,"getLinker");if(linker==null)continue;for(Object side:(List<?>)get(linker,"allBLinkers"))for(Object half:(Collection<?>)call(side,"getHalfLinkers")){Object sb=get(half,"sb");if(sb!=null&&seen.add(sb))builders.add(sb);}}
  List<String> rows=new ArrayList<>();Map<String,Object> chosen=new LinkedHashMap<>();for(Object sb:builders){Object start=get(sb,"startLinker");String kind=start.getClass().getSimpleName(),key=kind+get(sb,"yDir");chosen.putIfAbsent(key,sb);List<Object> ps=new ArrayList<>(),ls=new ArrayList<>();for(Object item:(List<?>)get(sb,"items")){String ik=item.getClass().getSimpleName();if(ik.equals("GlyphItem"))ps.add(get(item,"glyph"));if(ik.contains("LinkerItem")){Object l=get(item,"linker");if(!ls.contains(l))ls.add(l);}}Object source=call(start,"getSource"),headBox=call(source,"getBounds");for(String mode:new String[]{"empty","actual","reversed-duplicates"})for(boolean clip:new boolean[]{false,true}){List<Object> p=new ArrayList<>(ps),l=new ArrayList<>(ls);if(mode.equals("empty"))p.clear();if(mode.equals("reversed-duplicates")){if(!p.isEmpty())p.add(p.get(0));if(!l.isEmpty())l.add(l.get(0));Collections.reverse(p);Collections.reverse(l);}rows.add(observe(sb,p,l,clip?headBox:null,mode));}}
  for(Object sb:chosen.values()){Object start=get(sb,"startLinker"),stump=call(start,"getStump");java.awt.Rectangle b=stump==null?(java.awt.Rectangle)call(call(start,"getSource"),"getBounds"):(java.awt.Rectangle)call(stump,"getBounds");List<Object> ls=new ArrayList<>();for(Object item:(List<?>)get(sb,"items"))if(item.getClass().getSimpleName().contains("LinkerItem")){Object l=get(item,"linker");if(!ls.contains(l))ls.add(l);}for(String orientation:new String[]{"VERTICAL","HORIZONTAL"})for(int h:new int[]{3,7,15})for(int dx:new int[]{-3,0})for(int dy:new int[]{-40,0})for(String mode:new String[]{"empty","normal","reverse","duplicates","with-stump"}){Object a=glyph(b.x,b.y,2,h,orientation),v=glyph(b.x+dx,b.y+dy,2,15,orientation);List<Object> p=new ArrayList<>();if(!mode.equals("empty")){p.add(a);p.add(v);if(mode.equals("duplicates"))p.add(a);if(mode.equals("with-stump")&&stump!=null)p.add(stump);if(mode.equals("reverse"))Collections.reverse(p);}rows.add(observe(sb,p,new ArrayList<>(ls),null,"prescribed-"+mode));}}
  Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"native_outputs_used\":false,\"scope\":\"Actual first Laura system612 Head/Beam builders, original filter boundary only; stored candidate inputs and prescribed controls, not automatic discovery or whole STEMS epilog certification\",\"builders_observed\":"+builders.size()+",\"cases\":["+String.join(",",rows)+"]}");
 }catch(Exception e){throw new RuntimeException(e);}}
}
